import{_ as p,C as s,o as w,c as d,j as t,a,E as o,a8 as m}from"./chunks/framework.27XeWUA0.js";const r="/schedule-dashboard/thumbs/yt/GKSQYbELDzw-640.webp",u="/schedule-dashboard/thumbs/yt/GKSQYbELDzw-1280.webp",n="/schedule-dashboard/thumbs/yt/qFAbevIeJN0-640.webp",g="/schedule-dashboard/thumbs/yt/qFAbevIeJN0-1280.webp",i="/schedule-dashboard/thumbs/yt/tCOQhKgmD88-640.webp",b="/schedule-dashboard/thumbs/yt/tCOQhKgmD88-1280.webp",l="/schedule-dashboard/thumbs/yt/r64_O3DTVms-640.webp",v="/schedule-dashboard/thumbs/yt/r64_O3DTVms-1280.webp",C=JSON.parse('{"title":"AI Digest · Sun 22 Nov 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-11-22","routine":"digest"},"relativePath":"digest/2026-11-22.md","filePath":"digest/[date].md"}'),f={name:"digest/2026-11-22.md"},y=r+" 640w, "+u+" 1280w",k=n+" 640w, "+g+" 1280w",_=i+" 640w, "+b+" 1280w",S=l+" 640w, "+v+" 1280w",A={id:"ai-digest-·-sun-22-nov-2026",tabindex:"-1"};function D(I,e,T,K,N,O){const h=s("Badge"),c=s("DayFilter");return w(),d("div",null,[t("h1",A,[e[0]||(e[0]=a("AI Digest · Sun 22 Nov 2026 ",-1)),o(h,{type:"tip",text:"4"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-sun-22-nov-2026","aria-label":'Permalink to "AI Digest · Sun 22 Nov 2026 <Badge type="tip" text="4" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack daily digest — 22 Nov 2026 · run date Sun 22 Nov 2026 · 4 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(" There is 1 new talk (21 Nov, 10:30 PM IST): Osmantic's Ahmad Osman on running local AI in production, 56 minutes. It covers well-worn local-model ground, but the hardware, batching and continual-learning parts are concrete. Skim from 18:56.")]),t("p",null,[t("strong",null,"Better Stack:"),a(` There are 3 new videos. The freshest (22 Nov, 4:35 AM IST) covers Google's A2UI 1.0, where agents reply with native UI instead of text; it's worth watching. The NCM explainer, which checks the "31× faster than LLMs" claim, is also fresh ground. The Herdr Desktop review is mostly a repeat of recent agent-manager videos, apart from its customization.`)])],-1)),o(c),e[5]||(e[5]=m('<div class="grid cards2"><article class="it full" id="v-GKSQYbELDzw" data-title="What Runs Where? Local AI in Production — Ahmad Osman, Osmantic" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=GKSQYbELDzw" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+y+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=GKSQYbELDzw" target="_blank" rel="noopener">What Runs Where? Local AI in Production — Ahmad Osman, Osmantic</a></h3><div class="meta">AI Engineer · Ahmad Osman, founder &amp; CEO, Osmantic · uploaded 21 Nov, 10:30 PM IST · 56:09</div><div class="verdict v-skim"><b>Verdict:</b> skim from 18:56 — the hardware, batching and continual-learning parts are concrete, but much of the first 15 minutes is opinion on benchmarks and well-covered local-model ground.</div><div class="repeat">🔁 Repeat: &#39;open source / local models&#39; — seen 55 times before. New here: a full buyer&#39;s guide from someone who runs a 14× RTX 3090 basement rig, with concrete hardware race numbers and the case that continual learning can only happen locally.</div><div class="repeat">🔁 Repeat: &#39;inference / serving&#39; — seen 43 times before. New here: &quot;one inference engine per model, per chip, per workflow&quot; instead of llama.cpp for everything, plus the 100×-faster-tokenizer-gave-1.1% example.</div><div class="repeat">🔁 Repeat: &#39;RL fine-tuning small models&#39; — seen 9 times before. New here: Airbnb&#39;s 2B model hitting frontier quality at 1% of the cost.</div><div class="repeat">🔁 Repeat: &#39;GPU compute markets&#39; — seen 7 times before. New here: little beyond &quot;GPUs cost the same busy or idle&quot; and renting on the fly with Modal&#39;s CLI.</div><div class="repeat">🔁 Repeat: &#39;benchmark reliability&#39; — seen 4 times before. New here: his specific complaints (Artificial Analysis ranking Haiku 5.5 above DeepSeek V4.1 Flash; HLE showing a 50%+ open/closed gap while Terminal Bench has open models 2 points ahead).</div><div class="sh">Where local AI stands</div><ul><li><strong>Local was faster than the cloud:</strong> In a Hugging Face demo, Qwen 3.6 27B running locally decoded at 51 tokens/s versus 34 tokens/s for GPT-5.5 on OpenAI&#39;s cloud, with answers that looked about the same. His framing: open-source AI is an optimization problem, local AI is a user-experience problem (<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=90s" target="_blank" rel="noopener">1:30</a>–<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=215s" target="_blank" rel="noopener">3:35</a>)</li><li><strong>Agents now out-produce humans:</strong> OpenRouter data shows agents have generated more tokens than humans since February 2026, and long-horizon task length is doubling every four months. Most tokens go to DeepSeek V4.1 Flash, while most money goes to Opus 5.5 (<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=272s" target="_blank" rel="noopener">4:32</a>–<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=440s" target="_blank" rel="noopener">7:20</a>)</li><li><strong>Tokens per second is rarely the bottleneck:</strong> Agents spend most of their time waiting on shell commands and tool results, so even one RTX 3090 is useful. He doesn&#39;t trust benchmarks: Artificial Analysis ranks Haiku 5.5 above DeepSeek V4.1 Flash, and HLE and Terminal Bench disagree about the open/closed gap by more than 50 points (<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=222s" target="_blank" rel="noopener">3:42</a>–<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=540s" target="_blank" rel="noopener">9:00</a>)</li><li><strong>An agent-made trailer:</strong> His talk trailer was made end to end by Claude Code with Opus 5.5 (quotes, clips, music, text overlays) in 6 hours. Two RTX Pro 6000s handled photo, video and audio tagging and a MacBook did the editing, all on the team&#39;s own harness, Portal (<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=659s" target="_blank" rel="noopener">10:59</a>–<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=800s" target="_blank" rel="noopener">13:20</a>)</li></ul><div class="sh">Choosing hardware and engines</div><ul><li><strong>Quantize per layer, not all at 4-bit:</strong> Dynamic quantization keeps heavily used layers at 16- or 8-bit and pushes barely used ones down to 1-bit. Putting everything at 4-bit &quot;is probably going to nuke the model&quot;. GLM 5.3 at 4-bit keeps about 94% accuracy, versus 76.1% for DeepSeek 3.1 a year ago (<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=997s" target="_blank" rel="noopener">16:37</a>–<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=1110s" target="_blank" rel="noopener">18:30</a>)</li><li><strong>Buy for your workload:</strong> Prefill is compute-bound and decode is memory-bandwidth-bound. The M5 Ultra has about 1.2 TB/s against the DGX Spark&#39;s 273 GB/s, yet two Sparks still beat it because Apple&#39;s AI software is lacking. In a Hugging Face race, an RTX Pro 6000 reached about 1,300 tokens/s with 50 parallel requests while the other machines ran them one after another (<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=1136s" target="_blank" rel="noopener">18:56</a>–<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=1500s" target="_blank" rel="noopener">25:00</a>)</li><li><strong>The whole pipeline matters:</strong> A tokenizer made 100× faster only sped up the full request by 1.1%. A Nov 9 scheduling paper (he said he had only skimmed it) reports 1.5–3.14× throughput. He wants one inference engine per model per chip and invites PRs to his open-source ODS stack (<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=1440s" target="_blank" rel="noopener">24:00</a>–<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=1500s" target="_blank" rel="noopener">25:00</a>) (<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=1710s" target="_blank" rel="noopener">28:30</a>–<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=1870s" target="_blank" rel="noopener">31:10</a>)</li><li><strong>Give local agents search:</strong> A friend&#39;s local Qwen could not change his GPU&#39;s RGB fan colours until it got a search engine, because the tool came out after the model&#39;s training. ODS ships with search built in (<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=1976s" target="_blank" rel="noopener">32:56</a>–<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=2080s" target="_blank" rel="noopener">34:40</a>)</li></ul><div class="sh">Economics and what&#39;s next</div><ul><li><strong>Specialize from your own traces:</strong> Airbnb got frontier-quality results from a 2B model at 1% of the cost. He also warns that cheap API providers may quietly serve a different model, that GPUs cost the same busy or idle (so rent with tools like Modal&#39;s CLI for short jobs), and that owning hardware brings maintenance and silent failures (<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=2226s" target="_blank" rel="noopener">37:06</a>–<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=2640s" target="_blank" rel="noopener">44:00</a>)</li><li><strong>Intelligence density keeps rising:</strong> Qwen 3.6 27B dense beat the 15× larger 397B MoE a month after launch. DeepSeek V4.1 Flash shrank its KV cache about 437× (13 GB for 400K tokens versus 29 MB for 1K). Opus 4.5-level quality ran on one RTX Pro 6000 by April, so buy hardware for next year&#39;s models (<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=2720s" target="_blank" rel="noopener">45:20</a>–<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=2880s" target="_blank" rel="noopener">48:00</a>) (<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=3049s" target="_blank" rel="noopener">50:49</a>–<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=3070s" target="_blank" rel="noopener">51:10</a>)</li><li><strong>Continual learning has to be local:</strong> Big providers train for the average user, and markdown-file memory harnesses bloat over time. His proposed recipe is engrams (lookup tables on SSD or RAM), decision models and weight edits, and he hints that Osmantic is building it (<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=2887s" target="_blank" rel="noopener">48:07</a>–<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=2960s" target="_blank" rel="noopener">49:20</a>) (<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=3141s" target="_blank" rel="noopener">52:21</a>–<a href="https://www.youtube.com/watch?v=GKSQYbELDzw&amp;t=3240s" target="_blank" rel="noopener">54:00</a>)</li></ul></div></article><article class="it full" id="v-qFAbevIeJN0" data-title="Google Just Killed the Chatbot Reply (A2UI)" data-channel="Better Stack" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=qFAbevIeJN0" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+k+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=qFAbevIeJN0" target="_blank" rel="noopener">Google Just Killed the Chatbot Reply (A2UI)</a></h3><div class="meta">Better Stack · Andris, Better Stack · uploaded 22 Nov, 4:35 AM IST · 8:10</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — a clear, concrete intro to a new protocol with real token numbers.</div><div class="repeat">🔁 Repeat: &#39;production incidents&#39; — seen 5 times before. New here: the incident cards are driven through A2UI rather than a chat reply. The incident handling itself is a Better Stack demo.</div><div class="sh">What A2UI is</div><ul><li><strong>Agents reply with UI, not text:</strong> Google&#39;s open A2UI protocol has the agent send a JSON description of cards, forms or buttons, and your app draws them with its own native components (React, SwiftUI, Flutter, Kotlin). The agent can only use components registered in your catalog, and because the app gets data rather than code, a prompt-injected agent can&#39;t slip a script onto the page (<a href="https://www.youtube.com/watch?v=qFAbevIeJN0&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=qFAbevIeJN0&amp;t=122s" target="_blank" rel="noopener">2:02</a>)</li><li><strong>What 1.0 changed:</strong> A new screen now takes one message instead of three, agent and app can call each other&#39;s functions, and misuse of the catalog returns an error code the agent can use to fix itself. A compact &quot;A2UI Express&quot; format plus server-side Python &quot;macros&quot; saves tokens (<a href="https://www.youtube.com/watch?v=qFAbevIeJN0&amp;t=122s" target="_blank" rel="noopener">2:02</a>–<a href="https://www.youtube.com/watch?v=qFAbevIeJN0&amp;t=162s" target="_blank" rel="noopener">2:42</a>)</li><li><strong>Setup:</strong> On the agent side, Google&#39;s A2UI agent SDK, a catalog and a ready-made prompt snippet. On the app side, a renderer package, a message processor and a surface component, with button presses sent back to the agent as actions over SSE or WebSocket (<a href="https://www.youtube.com/watch?v=qFAbevIeJN0&amp;t=162s" target="_blank" rel="noopener">2:42</a>–<a href="https://www.youtube.com/watch?v=qFAbevIeJN0&amp;t=225s" target="_blank" rel="noopener">3:45</a>)</li></ul><div class="sh">Demo: cross-platform incident manager</div><ul><li><strong>Two apps, zero incident code:</strong> A SwiftUI iPhone app and a React web app share one Gemini-backed Python agent and only know A2UI&#39;s basic components. A dummy checkout incident created in Better Stack appears on both within seconds, pushed by the server without a model call. Acknowledging and lowering severity in the browser updates Better Stack through its API and syncs to the phone (<a href="https://www.youtube.com/watch?v=qFAbevIeJN0&amp;t=225s" target="_blank" rel="noopener">3:45</a>–<a href="https://www.youtube.com/watch?v=qFAbevIeJN0&amp;t=304s" target="_blank" rel="noopener">5:04</a>)</li><li><strong>Big token savings:</strong> For &quot;investigate&quot;, the model wrote 170 characters of A2UI Express, which the server expanded into almost 6,000 characters of JSON. The macros fill in error rates, user counts and logs on the server, so the model never sees that data (<a href="https://www.youtube.com/watch?v=qFAbevIeJN0&amp;t=304s" target="_blank" rel="noopener">5:04</a>–<a href="https://www.youtube.com/watch?v=qFAbevIeJN0&amp;t=369s" target="_blank" rel="noopener">6:09</a>)</li><li><strong>Styling and the MCP Apps difference:</strong> The whole look is one CSS file and one Swift file, though basic components can&#39;t be coloured individually. MCP Apps ship a whole web app into a sandboxed frame, while A2UI ships only a description and lets the host control the look (<a href="https://www.youtube.com/watch?v=qFAbevIeJN0&amp;t=369s" target="_blank" rel="noopener">6:09</a>–<a href="https://www.youtube.com/watch?v=qFAbevIeJN0&amp;t=412s" target="_blank" rel="noopener">6:52</a>)</li><li><strong>Caveats:</strong> It&#39;s early. The Android renderer is still at 0.9, the docs lag and the basic components are limited, but the protocol itself is stable (<a href="https://www.youtube.com/watch?v=qFAbevIeJN0&amp;t=412s" target="_blank" rel="noopener">6:52</a>–<a href="https://www.youtube.com/watch?v=qFAbevIeJN0&amp;t=460s" target="_blank" rel="noopener">7:40</a>)</li></ul></div></article><article class="it full" id="v-tCOQhKgmD88" data-title="New AI Architecture 31x Faster Than LLMs? NCM Explained." data-channel="Better Stack" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=tCOQhKgmD88" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+_+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=tCOQhKgmD88" target="_blank" rel="noopener">New AI Architecture 31x Faster Than LLMs? NCM Explained.</a></h3><div class="meta">Better Stack · Warren, Better Stack · uploaded 21 Nov, 1:30 PM IST · 7:39</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — a clear, skeptical walk through a new architecture paper and its headline number.</div><div class="repeat">🔁 Repeat: &#39;inference / serving&#39; — seen 43 times before. New here: a whole new way to generate text (coarse to fine), not a serving trick.</div><div class="sh">How NCM works</div><ul><li><strong>Why LLMs are slow:</strong> Stanford&#39;s Next-Concept Modeling (NCM) targets one-token-at-a-time decoding, where 1,000 output tokens means 1,000 sequential steps and the GPU sits waiting on memory bandwidth to reload the weights (<a href="https://www.youtube.com/watch?v=tCOQhKgmD88&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=tCOQhKgmD88&amp;t=114s" target="_blank" rel="noopener">1:54</a>)</li><li><strong>Text with levels of detail:</strong> Borrowing &quot;next-scale prediction&quot; from image generation, NCM trains a multi-scale residual VQ-VAE that encodes text into a hierarchy of discrete codes, each level storing what earlier ones missed. Final levels are sometimes dropped in training so early levels carry real meaning (<a href="https://www.youtube.com/watch?v=tCOQhKgmD88&amp;t=114s" target="_blank" rel="noopener">1:54</a>–<a href="https://www.youtube.com/watch?v=tCOQhKgmD88&amp;t=233s" target="_blank" rel="noopener">3:53</a>)</li><li><strong>Generating level by level:</strong> A frozen-representation transformer predicts each level&#39;s codes in parallel, and a decoder turns the result into tokens. In a German-to-English example, the early levels are mostly repetition and the warning about small firms and surveillance only appears further down (<a href="https://www.youtube.com/watch?v=tCOQhKgmD88&amp;t=233s" target="_blank" rel="noopener">3:53</a>–<a href="https://www.youtube.com/watch?v=tCOQhKgmD88&amp;t=292s" target="_blank" rel="noopener">4:52</a>)</li></ul><div class="sh">Checking the 31× claim</div><ul><li><strong>32 calls instead of 1,024:</strong> For 1,024 tokens of web text, NCM uses 32 generator calls, but each call does more work and the decoder adds cost, so it&#39;s not a direct comparison (<a href="https://www.youtube.com/watch?v=tCOQhKgmD88&amp;t=292s" target="_blank" rel="noopener">4:52</a>–<a href="https://www.youtube.com/watch?v=tCOQhKgmD88&amp;t=317s" target="_blank" rel="noopener">5:17</a>)</li><li><strong>The baseline is already parallel:</strong> The 31× speedup was on news summaries against Aurora LM, which is itself a diffusion model. The paper never times NCM against a normal token-by-token LLM (<a href="https://www.youtube.com/watch?v=tCOQhKgmD88&amp;t=317s" target="_blank" rel="noopener">5:17</a>–<a href="https://www.youtube.com/watch?v=tCOQhKgmD88&amp;t=345s" target="_blank" rel="noopener">5:45</a>)</li><li><strong>Quality is mixed:</strong> NCM beat the token-by-token model on news summaries but lost on translation (it catches up only by sampling several versions, which costs calls) and on open web text (<a href="https://www.youtube.com/watch?v=tCOQhKgmD88&amp;t=345s" target="_blank" rel="noopener">5:45</a>–<a href="https://www.youtube.com/watch?v=tCOQhKgmD88&amp;t=377s" target="_blank" rel="noopener">6:17</a>)</li><li><strong>Far from your desktop:</strong> It still needs memory for the model plus the decoder. Most experiments used about a 100M-parameter generator and the largest was 725M, versus GPT-3&#39;s 175B. His verdict: interesting, but not the end of LLMs (<a href="https://www.youtube.com/watch?v=tCOQhKgmD88&amp;t=377s" target="_blank" rel="noopener">6:17</a>–<a href="https://www.youtube.com/watch?v=tCOQhKgmD88&amp;t=459s" target="_blank" rel="noopener">7:39</a>)</li></ul></div></article><article class="it full" id="v-r64_O3DTVms" data-title="Herdr Desktop Is The Most Customizable Agent Orchestrator" data-channel="Better Stack" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=r64_O3DTVms" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+S+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=r64_O3DTVms" target="_blank" rel="noopener">Herdr Desktop Is The Most Customizable Agent Orchestrator</a></h3><div class="meta">Better Stack · Warren, Better Stack · uploaded 21 Nov, 8:30 PM IST · 5:58</div><div class="verdict v-skim"><b>Verdict:</b> skim from 3:11 — the customization is the only new part; the rest repeats recent agent-manager videos.</div><div class="repeat">🔁 Repeat: &#39;multi-agent / A2A&#39; — seen 31 times before. New here: Herdr&#39;s own desktop GUI. The run-many-agents-side-by-side idea is the same ground as the recent Orca and Rex videos.</div><div class="repeat">🔁 Repeat: &#39;always-on agents&#39; — seen 17 times before. New here: Herdr&#39;s lightweight SSH-only remote machines (no app needed on the remote box).</div><div class="sh">The app</div><ul><li><strong>The TUI, now as a desktop app:</strong> The new desktop app matches the old terminal UI feature for feature: spaces and agents in a sidebar, a real terminal on the right, tabs and split panes. Claude Code and Codex agents run side by side with progress shown per agent (<a href="https://www.youtube.com/watch?v=r64_O3DTVms&amp;t=61s" target="_blank" rel="noopener">1:01</a>–<a href="https://www.youtube.com/watch?v=r64_O3DTVms&amp;t=105s" target="_blank" rel="noopener">1:45</a>) (repeat)</li><li><strong>Agents on a remote machine:</strong> Under Settings you add a machine (his is a Mac Mini) and new spaces there connect over SSH, so agents keep running when the laptop sleeps. It&#39;s SSH-only, unlike Orca, Rex or Claude Code, which pair Tailscale with an app on the remote side (<a href="https://www.youtube.com/watch?v=r64_O3DTVms&amp;t=105s" target="_blank" rel="noopener">1:45</a>–<a href="https://www.youtube.com/watch?v=r64_O3DTVms&amp;t=191s" target="_blank" rel="noopener">3:11</a>) (repeat)</li></ul><div class="sh">Customization</div><ul><li><strong>Herdr 98 and community layouts:</strong> There are three stock looks, including a Windows 98 skin. The gallery at herdr.dev/gallery has prompts you paste into an agent to install layouts and mods, such as Herdr + Skillshare, Shep Herdr (separate models for assistant, worker and reviewer roles) and Pixel HQ (<a href="https://www.youtube.com/watch?v=r64_O3DTVms&amp;t=191s" target="_blank" rel="noopener">3:11</a>–<a href="https://www.youtube.com/watch?v=r64_O3DTVms&amp;t=264s" target="_blank" rel="noopener">4:24</a>)</li><li><strong>Build your own with a prompt:</strong> Following herdr.dev/guide, he had an agent build a Kanban layout with columns for needs-you, working and done, including a custom button (<a href="https://www.youtube.com/watch?v=r64_O3DTVms&amp;t=264s" target="_blank" rel="noopener">4:24</a>–<a href="https://www.youtube.com/watch?v=r64_O3DTVms&amp;t=295s" target="_blank" rel="noopener">4:55</a>)</li><li><strong>Mobile app and backing:</strong> A mobile app lets you manage agents on the go. Herdr was started by one developer, joined Y Combinator in August and raised a $6M seed in September with Shopify&#39;s Tobi Lütke among the backers (<a href="https://www.youtube.com/watch?v=r64_O3DTVms&amp;t=295s" target="_blank" rel="noopener">4:55</a>–<a href="https://www.youtube.com/watch?v=r64_O3DTVms&amp;t=323s" target="_blank" rel="noopener">5:23</a>)</li></ul></div></article></div>',1))])}const L=p(f,[["render",D]]);export{C as __pageData,L as default};
